from fastmcp.server import FastMCP


def create_openapi_mcp_server(
    openapi_spec: dict,
    client: httpx.AsyncClient,
    name: str = "OpenAPI MCP Server",
    **server_kwargs
) -> FastMCP:
    """
    Generate an MCP server from an OpenAPI 3.0 specification.

    Args:
        openapi_spec: OpenAPI 3.0 specification as a Python dictionary
        client: Configured httpx.AsyncClient with base URL already set
        name: Name for the MCP server (default: "OpenAPI MCP Server")
        **server_kwargs: Additional keyword arguments passed to FastMCP

    Returns:
        FastMCP server instance with tools generated from the OpenAPI spec
    """
    return FastMCP.from_openapi(
        openapi_spec=openapi_spec,
        client=client,
        name=name,
        **server_kwargs
    )


